"""Promote the current research release on the static homepage."""
from pathlib import Path
import re

root = Path(__file__).resolve().parent.parent
path = root / 'index.html'
page = path.read_text()
for name in ['announcement', 'latest-research', 'latest-styles']:
    page = re.sub(rf'<!-- home:{name}:start -->[\s\S]*?<!-- home:{name}:end -->', '', page)

styles = '''<!-- home:latest-styles:start --><style>
.home-news{display:block;border-bottom:1px solid var(--line-hi);background:var(--bg-raise);color:var(--fg);text-decoration:none;position:relative;z-index:3}.home-news-inner{max-width:1280px;margin:0 auto;padding:14px 32px;display:flex;align-items:center;gap:18px;font-size:14px;line-height:1.5}.home-news-tag{font:10px var(--f-mono);letter-spacing:.12em;color:var(--signal-2);white-space:nowrap}.home-news-title{font-weight:500}.home-news-arrow{margin-left:auto;font:11px var(--f-mono);white-space:nowrap;color:var(--signal-2)}.home-news:hover{background:var(--bg-sink)}.home-news:focus-visible{outline:2px solid var(--signal-2);outline-offset:-4px}
.home-latest{border-bottom:1px solid var(--line);background:radial-gradient(ellipse at 90% 50%,rgba(224,122,74,.035),transparent 55%),var(--bg)}.home-latest-inner{max-width:1280px;margin:0 auto;padding:64px 32px}.home-latest-header{display:flex;align-items:baseline;justify-content:space-between;gap:24px;padding-bottom:20px;margin-bottom:32px;border-bottom:1px solid var(--line-hi)}.home-latest-header h2{font-size:28px;letter-spacing:-.03em;font-weight:500;margin:0}.home-latest-header>a{font:11px var(--f-mono);color:var(--fg-3);text-decoration:none}.home-latest-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:56px;align-items:center}.home-latest-meta{font:10px/1.7 var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--signal-2);margin-bottom:18px}.home-latest h3{font-size:clamp(34px,3.8vw,52px);font-weight:500;line-height:1.08;letter-spacing:-.04em;margin:0 0 20px;text-wrap:balance}.home-latest h3 a{text-decoration:none;color:var(--fg)}.home-latest h3 a:hover{color:var(--signal-2)}.home-latest-summary{font-size:18px;line-height:1.75;color:var(--fg-2);max-width:54ch;margin:0 0 24px}.home-latest-note{font:11px/1.8 var(--f-mono);color:var(--fg-3);margin-bottom:24px}.home-latest-actions{display:flex;flex-wrap:wrap;gap:12px}.home-latest-actions a{display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:13px 18px;border:1px solid var(--line-hi);font:12px var(--f-mono);color:var(--fg);text-decoration:none;transition:background .18s,border-color .18s}.home-latest-actions a:first-child{background:var(--signal-2);border-color:var(--signal-2);color:var(--bg)}.home-latest-actions a:hover{border-color:var(--signal-2);background:var(--bg-raise)}.home-latest-actions a:first-child:hover{background:var(--fg)}.home-latest-visual{display:block;border:1px solid var(--line-hi);padding:10px;background:linear-gradient(135deg,var(--bg-raise),var(--bg));box-shadow:0 16px 40px #0003;min-width:0}.home-latest-visual img{display:block;width:100%;height:auto;margin:0}.home-latest-visual:focus-visible{outline:2px solid var(--signal-2);outline-offset:4px}.home-latest-more{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-top:40px;border-top:1px solid var(--line);padding-top:24px}.home-latest-more a{display:grid;grid-template-columns:1fr auto;gap:8px 16px;text-decoration:none;min-width:0;padding:4px 0}.home-latest-more time{grid-column:1/-1;color:var(--fg-3);font:10px var(--f-mono)}.home-latest-more strong{font-size:16px;line-height:1.5;font-weight:500;color:var(--fg)}.home-latest-more a>span{color:var(--signal-2)}.home-latest-more a:hover strong{color:var(--signal-2)}
@media(max-width:880px){.home-news-inner{padding:12px 24px;gap:6px 12px;flex-wrap:wrap}.home-news-tag{font-size:9px}.home-news-title{font-size:13px}.home-news-arrow{font-size:10px}.home-latest-inner{padding:40px 24px}.home-latest-header{margin-bottom:26px}.home-latest-header h2{font-size:25px}.home-latest-grid{grid-template-columns:1fr;gap:28px}.home-latest h3{font-size:38px}.home-latest-summary{font-size:17px}.home-latest-more{grid-template-columns:1fr;gap:22px}.home-latest-visual{padding:7px}}
@media(max-width:420px){.home-news-arrow{display:none}.home-news-title{flex-basis:100%}.home-latest h3{font-size:34px}.home-latest-actions a{font-size:11px;padding:13px 14px}.home-latest-header>a{font-size:10px}}
@media(prefers-reduced-motion:reduce){.home-latest *{transition:none!important}}
</style><!-- home:latest-styles:end -->'''

announcement = '''<!-- home:announcement:start --><a class="home-news" href="/ai-security/insight-agency-gap/" aria-label="New research: The Insight–Agency Gap. Read the paper."><span class="home-news-inner"><span class="home-news-tag">NEW RESEARCH / 28 OCT 2026</span><span class="home-news-title">The Insight–Agency Gap</span><span class="home-news-arrow">Read the paper ↗</span></span></a><!-- home:announcement:end -->'''

section = '''<!-- home:latest-research:start --><section class="home-latest" id="latest-research" aria-labelledby="latest-research-title"><div class="home-latest-inner"><div class="home-latest-header"><h2 id="latest-research-title">Latest research.</h2><a href="/research">Browse all research ↗</a></div><article class="home-latest-grid"><div><div class="home-latest-meta"><time datetime="2026-10-28">28 October 2026</time> · Research Session 001</div><h3><a href="/ai-security/insight-agency-gap/">The Insight–Agency Gap</a></h3><p class="home-latest-summary">When a model recognizes an inconsistency, does its behavior actually change? Eight proposed failure modes examine the gap between expressed insight, reliable correction, and observable action.</p><p class="home-latest-note">Exploratory case study · Evidence limits stated · Replication framework included</p><div class="home-latest-actions"><a href="/ai-security/insight-agency-gap/">Read the paper ↗</a><a href="/downloads/insight-agency-gap.md" download>Download manuscript ↓</a></div></div><a class="home-latest-visual" href="/ai-security/insight-agency-gap/" aria-label="Read The Insight–Agency Gap"><img src="/images/insight-agency-gap/homepage-gap.svg" width="1200" height="630" loading="lazy" alt="The Insight–Agency Gap: expressed recognition and observable behavior require separate verification."></a></article><div class="home-latest-more" aria-label="More recent research"><a href="/ai-security/premise-collision/"><time datetime="2026-08-05">05 AUGUST 2026</time><strong>Premise Collision: The Poisoned Fact and the True One</strong><span aria-hidden="true">↗</span></a><a href="/ai-security/nx-bit/"><time datetime="2026-08-04">04 AUGUST 2026</time><strong>Where Is My NX Bit? Instruction/Data Separation and Agent Identity</strong><span aria-hidden="true">↗</span></a></div></div></section><!-- home:latest-research:end -->'''

assert '<section class="hero-stage">' in page
page = page.replace('<section class="hero-stage">', announcement + '<section class="hero-stage">', 1)
page = page.replace('</section><div class="ss-ticker"', '</section>' + section + '<div class="ss-ticker"', 1)
page = page.replace('</head>', styles + '</head>', 1)
assert page.count('id="latest-research"') == 1
assert page.count('home:announcement:start') == 1
path.write_text(page)
print('Homepage now announces the paper above the hero and features it in Latest research.')
